import { readAccountLoan, previewAccountLoan, borrowAgainstAccount, repayAccountLoan, sweepSubaccounts } from '../app/account-loans.js';
import { get, subscribe, deriveCanSign } from '../app/store.js';
import { ethers } from '../app/contracts.js';
import { ETH_DIVISOR } from '../app/chain-config.js';
import { displayEthCompact } from '../app/scaling.js';
import { compactUiError } from '../app/ui-error.js';
import { openPanelPopup, closePanelPopup } from '../app/panel-popups.js';

export function openAccountLoan({ player, trigger, onSold, onClose } = {}) {
  closePanelPopup('liquidation', { restoreFocus: false });
  const panel = document.createElement('section');
  panel.className = 'panel-popup liquidation-popup';
  panel.id = 'panel-liquidation'; panel.dataset.panelPopup = 'liquidation'; panel.hidden = true;
  panel.setAttribute('role', 'dialog'); panel.setAttribute('aria-modal', 'true');
  panel.setAttribute('aria-labelledby', 'account-loan-title');
  panel.innerHTML = `<div class="panel-popup__window">
    <header class="panel-popup__header"><h2 id="account-loan-title">ACCOUNT LOAN</h2>
      <button type="button" class="panel-popup__close" data-panel-close aria-label="Close account loan">×</button></header>
    <div class="panel-popup__body">
      <label>Account ID <input data-loan="account" type="number" min="4" step="1" placeholder="Your main account"></label>
      <p data-loan="current"></p>
      <div data-loan="terms">
        <label>Repay before level <input data-loan="due" type="number" min="1" step="1"></label>
        <label>Amount (game ETH) <input data-loan="amount" type="text" inputmode="decimal" placeholder="Maximum available"></label>
        <p>Interest is 5% of principal per level used (at least one), plus 1% per unused level of your chosen term.</p>
        <p>At the due level, available account reserves repay the loan automatically. If they are insufficient, the lender takes this account and its family; your wallet’s native sDGNRS is burned when a main account is taken. Repay early to keep control.</p>
        <p>After 20 purchase days in a level, about half the principal is paid as whole current-level tickets. The rest is paid in ETH, or stETH if needed.</p>
      </div>
      <p data-loan="quote"></p>
      <p data-loan="status" role="status" aria-live="polite"></p>
      <label><input data-loan="consent" type="checkbox"> I accept the repayment terms and risk of losing the account.</label>
      <div class="liquidation-actions"><button type="button" data-loan="refresh">Refresh</button>
        <button type="button" data-loan="borrow" disabled>Borrow</button>
        <button type="button" data-loan="repay" disabled>Repay loan</button></div>
      <hr><label>Collect from subaccount IDs <input data-loan="sweep-ids" type="text" placeholder="Comma-separated IDs"></label>
      <p>Moves ETH winnings and FLIP to the current main account. Active ordinary subaccounts keep their prepaid AFKing balance.</p>
      <button type="button" data-loan="sweep">Collect balances</button>
    </div></div>`;
  document.body.appendChild(panel);
  const node = key => panel.querySelector(`[data-loan="${key}"]`);
  const eth = value => `${displayEthCompact(value, 12)} game ETH`;
  let account, quote, busy = false, closed = false, sequence = 0;
  const cleanups = [];
  const owns = () => deriveCanSign() && get('ui.mode') === 'self'
    && String(get('connected.address')).toLowerCase() === String(player).toLowerCase()
    && account?.payee === String(player).toLowerCase();
  function sync() {
    node('borrow').disabled = busy || !owns() || !quote?.eligible || !node('consent').checked;
    node('repay').disabled = busy || !owns() || !(account?.owed > 0n);
    node('refresh').disabled = busy;
    node('sweep').disabled = busy || !owns();
    for (const key of ['account', 'due', 'amount', 'consent', 'sweep-ids']) node(key).disabled = busy;
  }
  function invalidate() { sequence++; quote = null; account = null; node('quote').textContent = ''; node('consent').checked = false; sync(); }
  async function load() {
    const seq = ++sequence; busy = true; quote = null; node('consent').checked = false;
    node('status').textContent = 'Loading account and loan terms…'; sync();
    try {
      const next = await readAccountLoan({ player, accountId: node('account').value || undefined });
      if (closed || seq !== sequence) return;
      account = next;
      if (!account.accountId) throw new Error('This wallet has no game account.');
      node('account').value = String(account.accountId);
      node('due').min = String(account.level + 1); node('due').max = String(account.maxDueLevel);
      node('due').value ||= String(account.level + 5);
      node('terms').hidden = account.principal > 0n;
      node('borrow').hidden = account.principal > 0n; node('repay').hidden = !account.principal;
      node('current').textContent = `Account #${account.accountId} · Level ${account.level}`;
      if (account.principal) {
        node('quote').textContent = `Borrowed ${eth(account.principal)}; due at level ${account.dueLevel}. Repay now: ${eth(account.owed)}. Your claimable winnings cover up to ${eth(account.claimable)}; the remainder comes from your wallet.`;
        node('status').textContent = account.owed > 0n ? '' : 'The due level has arrived; repayment is no longer available.';
      } else {
        const value = node('amount').value.trim();
        const amount = value ? ethers.parseEther(value) / ETH_DIVISOR : undefined;
        const result = await previewAccountLoan({ player, accountId: account.accountId, dueLevel: node('due').value, amount });
        if (closed || seq !== sequence) return;
        quote = result;
        node('quote').textContent = `Available: ${eth(quote.maxPrincipal)}. Principal: ${eth(quote.principal)}. Payout: ${eth(quote.ethOut)} in ETH / stETH, plus ${eth(quote.ticketWei)} in tickets.`;
        node('status').textContent = quote.eligible ? '' : 'No loan is available for this account, term and amount. Eligible future tickets and lender funds are required; a main account may have at most five smurfs.';
      }
      if (!owns()) node('status').textContent += ' Connect the account owner wallet to act.';
    } catch (error) { if (!closed && seq === sequence) node('status').textContent = compactUiError(error, 'Could not load account loan.'); }
    finally { if (!closed && seq === sequence) { busy = false; sync(); } }
  }
  async function act(kind) {
    if (busy || node(kind).disabled) return;
    busy = true; node('status').textContent = 'Confirm the transaction in your wallet…'; sync();
    try {
      const result = kind === 'borrow' ? await borrowAgainstAccount({ player, accountId: account.accountId, dueLevel: quote.dueLevel, amount: quote.principal, minEthOut: quote.ethOut })
        : kind === 'repay' ? await repayAccountLoan({ player, accountId: account.accountId, maxOwed: account.owed })
          : await sweepSubaccounts({ player, accountIds: node('sweep-ids').value.split(',').map(value => value.trim()).filter(Boolean) });
      try { await onSold?.(result); } catch { /* regular polling retries the view refresh */ }
      if (!closed) { busy = false; await load(); }
    } catch (error) {
      if (!closed) { quote = null; node('consent').checked = false; node('status').textContent = compactUiError(error, 'Transaction did not complete. Refresh before retrying.'); }
    } finally { busy = false; if (!closed) sync(); }
  }
  for (const key of ['account', 'due', 'amount']) node(key).addEventListener('input', invalidate);
  node('consent').addEventListener('change', sync);
  node('refresh').addEventListener('click', () => { if (!busy) void load(); });
  for (const kind of ['borrow', 'repay', 'sweep']) node(kind).addEventListener('click', () => { void act(kind); });
  panel.addEventListener('app:panel-close', () => {
    if (closed) return; closed = true; sequence++; cleanups.forEach(fn => fn()); panel.remove(); onClose?.();
  });
  for (const path of ['connected.address', 'viewing.address', 'ui.mode']) cleanups.push(subscribe(path, () => closePanelPopup('liquidation', { restoreFocus: false })));
  cleanups.push(subscribe('ui.chainOk', sync));
  openPanelPopup('liquidation', trigger, panel); void load();
}
